nodes.append({
 "id": 6, "lang": "English", "words": "turban", "verdict": "confirmed",
 "derivation": "English turban is first recorded in the 1560s, borrowed from French turbant/turban; earlier English spellings (turbant, turribant, tolibant, tulipant - Skeat) still show the -l- of the Turkish form. The sense stayed 'oriental head-wrap' throughout. The whole chain Persian dulband > Turkish tülbend > Italian turbante > French turbant > English turban is uncontroversial.",
