   {"src": "NYB", "where": "Manual II, Glossary s.v. bandak", "stance": "supports", "note": "'bandak [bndk'; inscr. BD-k] servant, slave ... OP bandaka-; MPrth bndg; MPrs bng = bannag < bandak; Paz. banda, NP bandah.'"}
 ]})

nodes.append({
